pid_t p = fork();

if (p < 0) {
    perror("fork failed");
    return 1;
}

if (p == 0) {
    // Child process: Execute new isolated task
    // Shared memory is CoW (Copy on Write) efficient
    printf("Child PID: %d\n", getpid());
    exit(0);
}

// Parent process
int status;
wait(&status); // Wait for resource cleanup
printf("Parent finished, child status: %d\n", status);
